//
//  Real AV1 temporal units captured from a live Sunshine host (3024x1890, Main8,
//  4:2:0). Embedded as base64 so tests need no bundle resources. The key frame is
//  TD + sequence-header + FRAME OBUs (valid bytes end at 407, padded to 1368); the
//  P-frame is TD + FRAME (valid end at 104, padded to 1368).
//

import Foundation

enum AV1Fixtures {
    static let keyFrame = Data(base64Encoded: keyFrameB64)!
    static let pFrame   = Data(base64Encoded: pFrameB64)!

    private static let keyFrameB64 = ""
    private static let pFrameB64 = ""
}
